item.text:
{
  "status": "Ready",
  "current_position": {
    "confirmed": [
      {
        "id": "CP-001",
        "statement": "The escalation is implemented as a solution-aware Power Automate cloud flow; an agent is not used because the trigger, rules, recipients, retry policy, and output are deterministic.",
        "basis": "Current approved component decision supplied for this slice and explicitly closed to reconsideration.",
        "source_refs": [
          "user-input:approved-component-decision"
        ]
      },
      {
        "id": "CP-002",
        "statement": "A qualifying service-request status change must validate the request and recipient, create one idempotent escalation record, send one synthetic notification through an approved connection reference, expose the outcome to the operator, and emit correlation telemetry.",
        "basis": "Observable end-to-end outcome supplied in the request.",
        "source_refs": [
          "user-input:slice-requirements"
        ]
      },
      {
        "id": "CP-003",
        "statement": "The brief must define failure, retry, duplicate-event, deployment, and rollback evidence without claiming implementation or runtime verification.",
        "basis": "Delivery-control requirements supplied in the request and the skill proof-boundary contract.",
        "source_refs": [
          "user-input:evidence-requirements",
          "skill:power-platform-incremental-delivery-v0.1.0"
        ]
      }
    ],
    "assumptions": [
      {
        "id": "AS-001",
        "statement": "The operator uses an organisational Microsoft model-driven service-request application backed by Dataverse.",
        "impact": "The operator outcome can be exposed through a related Escalations view or subgrid using platform-native accessibility and security behavior.",
        "validation_required": "Confirm the actual operator host and form/view placement before implementation.",
        "source_refs": [
          "bounded-assumption:operator-host"
        ]
      },
      {
        "id": "AS-002",
        "statement": "The service-request table exposes a status or status-reason field, a stable row identifier, and a Dataverse concurrency token or row version.",
        "impact": "The flow can identify qualifying transitions, reject stale events, and build a stable event-level idempotency key.",
        "validation_required": "Map these roles to current solution schema names before implementation; create missing solution-aware columns only through the authorised build workflow.",
        "source_refs": [
          "bounded-assumption:service-request-schema"
        ]
      },
      {
        "id": "AS-003",
        "statement": "The approved notification connector accepts a caller-supplied idempotency or deduplication key, or has an approved equivalent that prevents duplicate delivery after an ambiguous retry.",
        "impact": "The same escalation event can be retried without producing more than one logical notification.",
        "validation_required": "Verify the connector contract before implementation. If it cannot provide equivalent duplicate protection, pause the notification portion and obtain an amended integration decision.",
        "source_refs": [
          "bounded-assumption:notification-idempotency"
        ]
      },
      {
        "id": "AS-004",
        "statement": "Only synthetic service-request and recipient data are used for build and test evidence.",
        "impact": "No confidential organisational data needs to cross into the personal OpenAI reasoning zone.",
        "validation_required": "Test-data preparation must confirm synthetic classification before use.",
        "source_refs": [
          "user-input:synthetic-service-request"
        ]
      }
    ],
    "open_questions": [],
    "rejected": [
      {
        "id": "RJ-001",
        "decision": "Use an agent to interpret or perform the escalation.",
        "reason": "The supplied approved decision assigns this deterministic workflow to a solution-aware cloud flow.",
        "reconsider_if": "Not within this slice; only a separately authorised architecture change supported by new material evidence may reopen it."
      }
    ],
    "superseded": []
  },
  "boundary": {
    "zone": "personal-openai",
    "data_classification": "synthetic",
    "cross_zone_transfer": "permitted"
  },
  "slice": {
    "outcome": "For each current, qualifying synthetic service-request status transition, the system produces one durable escalation outcome and no more than one logical notification; the operator can see the correlated result, including validation, conflict, retry, or terminal failure.",
    "entry": "Persona: service-request operator. Host: assumed organisational model-driven app. Entry point: the operator saves a service request with a qualifying status or status reason. A solution-aware Dataverse row-modified trigger, filtered to the status column and qualifying values, starts the cloud flow with the request identifier, trigger row version, and flow-run context.",
    "validation": "Load the current request using least-privilege access and verify existence, qualifying status, required request fields, recipient presence and approved synthetic format, recipient allowlist or routing rule, and caller access. Compare the trigger row version with the current concurrency token before side effects. A stale or superseded event performs no notification, emits a conflict outcome and correlation ID, and instructs the operator to reload and reconcile. Recheck status and version immediately before dispatch. Validation errors are recorded as a terminal escalation outcome when the request remains current.",
    "persistence_or_action": "The cloud flow is the sole owner of this escalation lifecycle. Derive an idempotency key from request ID, qualifying status value, trigger row version, and escalation-policy version. Create the Escalation row against a Dataverse alternate key containing that value. The successful creator owns dispatch; a duplicate-key loser reads the existing row, emits a duplicate outcome, and exits without notification. Persist correlation ID, expected request version, policy version, outcome, retry count, timestamps, and sanitized error code. Send through the approved solution connection reference using the same idempotency key, then conditionally transition the escalation from Pending or Retrying to Sent, ValidationFailed, Conflict, or Failed. No handler writes the originating request.",
    "feedback": "The related Escalations view or subgrid shows Pending while processing, Sent on accepted notification, ValidationFailed for correctable request or recipient input, Conflict for stale data, Retrying with attempt count and next retry state, Failed with a sanitized operator action, and Duplicate without a second action. Permission failures reveal no recipient or connector details. Empty state explains that no qualifying escalation has occurred. Long messages are truncated with an accessible detail view; native keyboard, focus, responsive, and screen-reader behavior is retained. Conflict feedback tells the operator to reload and reconcile before resubmitting.",
    "telemetry": "Generate a privacy-safe correlation ID at flow entry and carry it through the escalation row, notification idempotency header or field, flow scopes, and monitoring events. Emit event type, policy version, environment role, duration, attempt number, outcome, duplicate or conflict flag, sanitized connector/error category, and escalation ID. Exclude request descriptions, message bodies, recipient addresses, personal identifiers, connection details, secrets, and raw connector responses.",
    "evidence": "Keep proof levels separate: source inspection and static solution validation prove configuration only; automated tests and solution checker results prove the tested build; exported package inspection proves component, dependency, connection-reference, alternate-key, and environment-variable integrity; import/configuration readback proves target binding and activation; runtime end-to-end evidence proves only the observed synthetic success, validation, conflict, retry, duplicate, failure, and replay cases. No implementation, package, deployment, or runtime evidence has yet been observed.",
    "scope": [
      "Solution-aware automated Dataverse cloud flow for qualifying status changes",
      "Escalation table with alternate-key idempotency and operator-visible outcomes",
      "Deterministic request and recipient validation",
      "One synthetic notification through an approved solution connection reference",
      "Privacy-safe correlation telemetry and operational outcomes",
      "Focused success, failure, retry, stale-event, concurrent-change, duplicate-event, deployment, and rollback evidence"
    ],
    "exclusions": [
      "Agent, generative AI, prompt, or autonomous decision-making",
      "Live tenant access, authentication, deployment, or connection binding in this brief",
      "Confidential, personal, or customer service-request content",
      "Changes to the approved escalation component decision",
      "Unrelated service-request lifecycle automation",
      "Direct writes to the originating request by the escalation flow"
    ]
  },
  "architecture": {
    "experience": [
      {
        "id": "EXP-001",
        "decision": "Expose escalation state in a secured related view or subgrid on the existing operator service-request surface.",
        "rationale": "This gives the operator a durable, refreshable outcome without introducing a custom UI or a second lifecycle owner.",
        "evidence_status": "Assumption"
      },
      {
        "id": "EXP-002",
        "decision": "Provide explicit Pending, Sent, ValidationFailed, Conflict, Retrying, Failed, and Duplicate states with sanitized guidance.",
        "rationale": "Operators can distinguish asynchronous progress, correctable input, concurrency conflicts, and terminal operational failures.",
        "evidence_status": "Confirmed"
      }
    ],
    "data": [
      {
        "id": "DAT-001",
        "decision": "Store one Escalation row per qualifying request event, protected by an alternate key derived from request ID, qualifying status, trigger row version, and policy version.",
        "rationale": "The durable unique constraint is the authoritative duplicate-action boundary and remains effective under concurrent flow runs.",
        "evidence_status": "Confirmed"
      },
      {
        "id": "DAT-002",
        "decision": "Keep the originating request read-only within this flow and use its concurrency token for stale-event checks.",
        "rationale": "This preserves one owner for request writes and prevents a stale automation run from overwriting newer operator changes.",
        "evidence_status": "Confirmed"
      }
    ],
    "integration": [
      {
        "id": "INT-001",
        "decision": "Use one solution-aware Power Automate cloud flow with Dataverse trigger and actions plus one approved notification connection reference.",
        "rationale": "This implements the supplied deterministic component decision and keeps environment bindings deployable.",
        "evidence_status": "Confirmed"
      },
      {
        "id": "INT-002",
        "decision": "Carry the escalation idempotency key into the notification boundary and require downstream duplicate protection for ambiguous retries.",
        "rationale": "Dataverse idempotency alone cannot prove a single external delivery if a notification succeeds but its response or subsequent status update is lost.",
        "evidence_status": "Assumption"
      }
    ],
    "ai": [
      {
        "id": "AI-001",
        "decision": "Use no AI or agent component in this slice.",
        "rationale": "All routing, validation, retry, recipient, and output decisions are deterministic and the approved component decision is settled.",
        "evidence_status": "Confirmed"
      }
    ],
    "security": [
      {
        "id": "SEC-001",
        "decision": "Bind connection references to approved organisational service identities with least-privilege rights to read requests, create and update escalations, and invoke only the approved notification action.",
        "rationale": "This limits the automation blast radius and avoids personal connections or embedded credentials.",
        "evidence_status": "Assumption"
      },
      {
        "id": "SEC-002",
        "decision": "Apply table, row, and field security so operators see permitted escalation outcomes but not connector diagnostics or recipient details.",
        "rationale": "Operator feedback remains useful without exposing sensitive operational information.",
        "evidence_status": "Confirmed"
      },
      {
        "id": "SEC-003",
        "decision": "Use only synthetic allowlisted recipients and verify the solution and connector comply with the target environment DLP policy.",
        "rationale": "This enforces the stated proof boundary and prevents unintended external data transfer.",
        "evidence_status": "Assumption"
      }
    ],
    "operations": [
      {
        "id": "OPS-001",
        "decision": "Use scoped error handling with explicit transient, permanent, ambiguous-dispatch, duplicate, and conflict outcomes.",
        "rationale": "Each failure class receives deterministic retry or terminal handling and produces reviewable evidence.",
        "evidence_status": "Confirmed"
      },
      {
        "id": "OPS-002",
        "decision": "Retry idempotent Dataverse operations with bounded exponential backoff; retry notification dispatch only with the same downstream idempotency key, and route exhausted or non-idempotent ambiguous outcomes to Failed or manual reconciliation without blind replay.",
        "rationale": "This supports recovery while preventing duplicate notifications.",
        "evidence_status": "Confirmed"
      },
      {
        "id": "OPS-003",
        "decision": "Emit privacy-safe correlation telemetry for success, validation failure, retry, duplicate, stale conflict, permission failure, and terminal failure.",
        "rationale": "Operations can reconcile flow runs, escalation rows, and notification acknowledgements without logging payload content.",
        "evidence_status": "Confirmed"
      }
    ],
    "alm": [
      {
        "id": "ALM-001",
        "decision": "Package the flow, tables and columns, alternate key, views, connection references, environment-variable definitions, security artifacts, and required dependencies in one solution.",
        "rationale": "The complete vertical slice can be imported, configured, validated, and rolled back as a versioned unit.",
        "evidence_status": "Confirmed"
      },
      {
        "id": "ALM-002",
        "decision": "Resolve environment-specific qualifying status values, policy version, retry limits, telemetry destination, recipient allowlist, and connection bindings through deployment configuration rather than embedded values.",
        "rationale": "This keeps the solution portable and makes target configuration independently reviewable.",
        "evidence_status": "Confirmed"
      }
    ]
  },
  "delegations": [],
  "acceptance_criteria": [
    {
      "id": "AC-001",
      "given": "A current synthetic service request has all required fields, an approved synthetic recipient, and a non-qualifying status.",
      "when": "The operator changes the status to a configured qualifying value and saves once.",
      "then": "One escalation row is created, one logical notification is accepted using its idempotency key, the escalation becomes Sent, and the operator can see the matching correlation ID and outcome.",
      "evidence": "Runtime request version, one escalation row, connector acknowledgement, operator-view capture, flow-run trace, and privacy-safe telemetry record with the same correlation ID."
    },
    {
      "id": "AC-002",
      "given": "The same qualifying trigger event is delivered or replayed more than once.",
      "when": "Concurrent or sequential flow runs derive the same idempotency key.",
      "then": "Exactly one run creates the escalation and owns dispatch; all other runs record or emit Duplicate and perform no notification action.",
      "evidence": "Parallel run traces, alternate-key result, one escalation-row query result, one connector acknowledgement, and duplicate telemetry."
    },
    {
      "id": "AC-003",
      "given": "A qualifying event was captured but the request changes before the flow validates its trigger version.",
      "when": "The flow compares the trigger version with the current concurrency token.",
      "then": "It rejects the stale event without overwriting the request or sending a notification, emits Conflict telemetry, and tells the operator to reload and reconcile.",
      "evidence": "Both request versions, unchanged newer request, no notification acknowledgement, conflict outcome, correlation telemetry, and operator feedback."
    },
    {
      "id": "AC-004",
      "given": "The request remains current but its recipient is missing, malformed, disallowed, or not synthetic.",
      "when": "Recipient validation runs.",
      "then": "No notification is sent, a sanitized ValidationFailed outcome is visible to the permitted operator, and telemetry contains no recipient value.",
      "evidence": "Validation test result, escalation outcome, absence of connector invocation, operator-view capture, and redacted telemetry inspection."
    },
    {
      "id": "AC-005",
      "given": "A transient dependency failure occurs before or during an idempotent operation.",
      "when": "The configured bounded retry policy executes.",
      "then": "Retries use the same correlation and idempotency keys, attempt counts are recorded, and the final outcome is Sent or Failed without a second logical notification.",
      "evidence": "Injected-failure trace, retry timestamps and count, stable keys, connector deduplication evidence, escalation outcome, and telemetry."
    },
    {
      "id": "AC-006",
      "given": "The retry limit is exhausted or a permanent connector, permission, or configuration error occurs.",
      "when": "The failure scope completes.",
      "then": "The escalation becomes Failed, no blind replay occurs, the operator receives sanitized guidance, and diagnostics remain restricted to authorised operations personnel.",
      "evidence": "Failure-scope trace, escalation outcome, security-role comparison, operator feedback, and restricted diagnostic event."
    },
    {
      "id": "AC-007",
      "given": "The versioned solution is imported into a test environment and all prerequisites are bound.",
      "when": "Post-deployment checks and the synthetic smoke test run.",
      "then": "The flow is enabled, connection references and configuration resolve correctly, the alternate key is active, and the end-to-end success and duplicate cases pass.",
      "evidence": "Import result, component and dependency inventory, configuration readback, enabled-flow state, alternate-key readback, and runtime smoke-test bundle."
    },
    {
      "id": "AC-008",
      "given": "A rollback trigger is approved after deployment.",
      "when": "The documented rollback procedure is executed.",
      "then": "New escalation processing stops, the prior solution behavior is restored, existing escalation evidence is retained, and no pending event is replayed without reconciliation.",
      "evidence": "Change approval, before-and-after solution versions, flow activation states, retained-row check, queue or pending-state reconciliation, and rollback smoke test."
    }
  ],
  "negative_paths": [
    {
      "id": "NP-001",
      "condition": "The trigger event is stale because the current request row version differs or the status is no longer qualifying.",
      "expected_behavior": "Perform no write to the request and no notification; emit Conflict with a correlation ID and direct the operator to reload and reconcile.",
      "evidence": "Concurrent-change trace, both request versions, no connector acknowledgement, and conflict telemetry."
    },
    {
      "id": "NP-002",
      "condition": "The same event is delivered again or two flow runs race on the same idempotency key.",
      "expected_behavior": "The Dataverse alternate key selects one creator; duplicate runs read the existing escalation and exit without dispatch.",
      "evidence": "Concurrent traces, duplicate-key response, one escalation row, and one logical notification acknowledgement."
    },
    {
      "id": "NP-003",
      "condition": "The recipient is absent, invalid, outside the synthetic allowlist, or prohibited by policy.",
      "expected_behavior": "Create or finalize a sanitized ValidationFailed outcome for the current event, send nothing, and omit recipient values from logs.",
      "evidence": "Validation matrix, zero notification invocation, visible operator outcome, and telemetry-content inspection."
    },
    {
      "id": "NP-004",
      "condition": "The flow identity lacks permission to read the request or create or update the escalation.",
      "expected_behavior": "Fail safely, expose only generic operator guidance, emit a restricted permission category, and do not attempt notification.",
      "evidence": "Least-privilege negative test, access-denied trace, zero connector invocation, and role-scoped diagnostic visibility."
    },
    {
      "id": "NP-005",
      "condition": "The notification connector returns a transient throttling or service error.",
      "expected_behavior": "Apply bounded backoff using the same idempotency key, record attempts, and stop at the configured limit.",
      "evidence": "Injected connector responses, retry trace, stable idempotency key, attempt count, and final outcome."
    },
    {
      "id": "NP-006",
      "condition": "Notification acceptance is ambiguous and downstream idempotency cannot be confirmed.",
      "expected_behavior": "Do not blindly resend; mark the escalation Failed or ReconciliationRequired, alert authorised operations, and resolve against downstream evidence.",
      "evidence": "Ambiguous-response trace, absence of unkeyed replay, restricted operational alert, and reconciliation record."
    },
    {
      "id": "NP-007",
      "condition": "The flow is triggered by a change to an unrelated request field or by a non-qualifying status.",
      "expected_behavior": "The trigger filter or first guard terminates with no escalation, notification, or operator error.",
      "evidence": "Trigger-condition test, absence of escalation row, and absence of connector invocation."
    },
    {
      "id": "NP-008",
      "condition": "A stale form submission attempts to overwrite a newer service-request version.",
      "expected_behavior": "The owning request update path rejects the stale write without losing either version; no qualifying escalation is inferred from the rejected submission, and the operator reloads and reconciles.",
      "evidence": "Concurrency test from the request write owner, retained newer row, rejected version evidence, and no escalation side effect."
    }
  ],
  "tests": [
    {
      "id": "TEST-001",
      "class": "functional",
      "scope": "Qualifying synthetic status transition through Sent operator outcome.",
      "expected": "One escalation, one logical notification, one correlated Sent outcome.",
      "evidence_required": "Automated result plus correlated runtime request, escalation, notification acknowledgement, operator view, and telemetry.",
      "status": "planned"
    },
    {
      "id": "TEST-002",
      "class": "reliability",
      "scope": "Sequential replay and concurrent duplicate delivery of the same trigger event.",
      "expected": "Alternate-key enforcement permits one owner and zero duplicate notifications.",
      "evidence_required": "Parallel flow traces, Dataverse key evidence, row count, connector acknowledgement count, and duplicate telemetry.",
      "status": "planned"
    },
    {
      "id": "TEST-003",
      "class": "reliability",
      "scope": "Concurrent request change after trigger capture.",
      "expected": "The stale event is rejected, the newer request survives unchanged, no notification is sent, and Conflict is visible.",
      "evidence_required": "Before and after versions, concurrency assertion, no connector invocation, operator outcome, and correlation telemetry.",
      "status": "planned"
    },
    {
      "id": "TEST-004",
      "class": "functional",
      "scope": "Missing, malformed, disallowed, and non-synthetic recipient matrix.",
      "expected": "Each case fails validation without notification and exposes a sanitized correction path.",
      "evidence_required": "Parameterized validation results, escalation outcomes, connector invocation count, and telemetry redaction checks.",
      "status": "planned"
    },
    {
      "id": "TEST-005",
      "class": "reliability",
      "scope": "Transient Dataverse and notification failures followed by recovery or retry exhaustion.",
      "expected": "Bounded backoff, stable keys, correct attempt count, and no duplicate logical delivery.",
      "evidence_required": "Fault-injection traces, retry timing, stable correlation and idempotency keys, connector deduplication record, and terminal outcomes.",
      "status": "planned"
    },
    {
      "id": "TEST-006",
      "class": "security",
      "scope": "Least-privilege flow identity, operator row visibility, synthetic recipient allowlist, DLP, and telemetry content.",
      "expected": "Permitted actions succeed; denied actions fail safely; no message body, recipient value, secret, or raw connector response appears in telemetry.",
      "evidence_required": "Role matrix, access tests, DLP validation, connection-owner readback, and sanitized log inspection.",
      "status": "planned"
    },
    {
      "id": "TEST-007",
      "class": "accessibility",
      "scope": "Operator escalation view across pending, success, validation, conflict, retry, failure, empty, long-content, and narrow-screen states.",
      "expected": "Outcomes are keyboard accessible, focus is predictable, labels and status text are announced, and meaning does not depend on color.",
      "evidence_required": "Keyboard and screen-reader checks plus responsive captures for each material state.",
      "status": "planned"
    },
    {
      "id": "TEST-008",
      "class": "performance",
      "scope": "Representative burst of distinct and duplicate qualifying synthetic events.",
      "expected": "The agreed processing target is met without throttling-induced duplicate delivery or unbounded backlog.",
      "evidence_required": "Approved target, event timestamps, flow duration and concurrency metrics, throttling observations, and backlog depth.",
      "status": "planned"
    },
    {
      "id": "TEST-009",
      "class": "alm",
      "scope": "Solution contents, dependencies, alternate key, environment variables, connection references, flow definition, and absence of embedded environment values.",
      "expected": "The exported artifact is complete, versioned, portable, and statically valid.",
      "evidence_required": "Solution checker result, unpacked-package review, dependency inventory, and configuration scan.",
      "status": "planned"
    },
    {
      "id": "TEST-010",
      "class": "deployment",
      "scope": "Clean import, configuration binding, activation, and post-deployment synthetic smoke test.",
      "expected": "Import and readback succeed and the success, validation, duplicate, and conflict paths behave as specified.",
      "evidence_required": "Import logs, configuration readback, component states, flow activation, and correlated runtime test bundle.",
      "status": "planned"
    },
    {
      "id": "TEST-011",
      "class": "rollback",
      "scope": "Disable the new flow, restore the prior solution version, retain evidence, and reconcile pending escalations.",
      "expected": "New processing stops, prior behavior returns, historical rows remain, and no pending notification is blindly replayed.",
      "evidence_required": "Rollback authorization, solution and activation readback, retained-data check, reconciliation record, and post-rollback smoke test.",
      "status": "planned"
    }
  ],
  "deployment": {
    "authorization_status": "not-requested",
    "target_zone": "organisational-microsoft",
    "environments": [
      "development",
      "test",
      "production"
    ],
    "prerequisites": [
      "Authorised solution publisher and versioning convention",
      "Confirmed service-request schema mappings and qualifying status values",
      "Escalation schema with active alternate key and required security roles",
      "Approved organisational service identity and least-privilege connection bindings",
      "Approved notification connector with verified idempotency or equivalent duplicate-delivery protection",
      "Target-environment DLP approval and synthetic recipient allowlist",
      "Configured policy version, retry limits, telemetry destination, and operator-view placement",
      "Successful static checks, focused automated tests, package inspection, and rollback rehearsal in a non-production environment",
      "Explicit deployment authorization for each target environment"
    ],
    "steps": [
      "Build and validate the complete slice in the development solution without live or confidential data.",
      "Export the intended managed artifact and verify components, dependencies, alternate key, flow definition, connection references, and environment-variable definitions.",
      "Import into test, bind approved connection references and configuration, assign least-privilege roles, and read back all bindings.",
      "Activate the flow only after prerequisites and the notification idempotency contract are verified.",
      "Run correlated synthetic success, validation, concurrent-change, duplicate, retry, permission, and failure tests.",
      "Obtain change approval and import the exact tested artifact into production using the authorised deployment path.",
      "Bind production-approved connections and configuration, verify activation and monitoring, then execute only the approved synthetic smoke path."
    ],
    "post_deploy_checks": [
      "Confirm the imported solution version and component inventory match the approved artifact.",
      "Read back flow activation, trigger filters, environment-variable values, connection-reference bindings, and service identity.",
      "Confirm the Escalation alternate key is active and the operator view is secured and visible.",
      "Confirm telemetry reaches the approved destination without excluded payload fields.",
      "Run one qualifying synthetic event and verify correlated Sent evidence.",
      "Replay the same event and verify Duplicate with no second logical notification.",
      "Run the concurrent-change case and verify Conflict, preserved newer data, and no notification.",
      "Confirm monitoring and rollback owners can access the required operational evidence."
    ],
    "evidence_required": [
      "Approved artifact identifier and integrity record",
      "Static validation, automated test, and package-integrity results",
      "Import logs and dependency resolution",
      "Configuration, connection, identity, security-role, alternate-key, and activation readback",
      "Correlated runtime evidence for success, validation, conflict, retry, duplicate, permission, and terminal failure",
      "Deployment authorization and rollback readiness record"
    ]
  },
  "rollback": {
    "triggers": [
      "Duplicate logical notification is observed for one idempotency key",
      "The flow overwrites or otherwise corrupts a newer service-request state",
      "Connection, DLP, permission, or telemetry configuration violates the approved boundary",
      "Unrecoverable processing failures or backlog exceed the approved operational threshold",
      "The deployed solution version or bindings differ from the approved artifact",
      "Operator outcomes are materially unavailable or misleading"
    ],
    "steps": [
      "Obtain rollback authorization and record the triggering evidence and correlation IDs.",
      "Disable the new cloud flow to stop additional trigger processing.",
      "Suspend manual replay and capture Pending, Retrying, Failed, and ambiguous-dispatch escalation identifiers.",
      "Restore or reactivate the previously approved solution version and connection bindings through the authorised ALM path.",
      "Verify prior component activation, request behavior, security, and monitoring configuration.",
      "Reconcile each captured escalation against downstream notification evidence before any resend or closure.",
      "Run the approved post-rollback synthetic smoke test and communicate the sanitized operational status."
    ],
    "data_considerations": [
      "Retain escalation rows, correlation IDs, outcomes, and audit evidence; do not delete records to conceal failed processing.",
      "Do not change originating service-request rows during rollback.",
      "Preserve idempotency keys so restored or repaired processing cannot resend completed notifications.",
      "Restrict failed-message and connector diagnostics to authorised operations roles.",
      "Apply the approved retention policy to synthetic evidence after incident and release review."
    ],
    "owner": "Authorised Power Platform release owner with the flow operations owner",
    "evidence_required": [
      "Rollback approval and trigger evidence",
      "Before-and-after solution version and flow activation readback",
      "Connection, role, and configuration readback",
      "Retained escalation-row and idempotency-key verification",
      "Pending and ambiguous-event reconciliation record",
      "Post-rollback synthetic smoke-test result and monitoring confirmation"
    ]
  },
  "next_action": "Hand this Ready brief to the authorised implementation workflow; first confirm the operator host and schema mappings and prove the approved notification connection's idempotency contract, then implement the development slice with synthetic data only. No implementation, deployment, package integrity, target configuration, or runtime behavior is yet verified."
}
